mapper.select:
select billId, regDentistId, employeeName, orderDate, orderNum, billDate, billNum, patientId, `name`, mobile, originalPrice, privilegeAmount, actualAmount, receivedAmount, debtAmount from ( SELECT bill_id AS billId, btp.registered_dentist_id AS regDentistId, btp.employee_name AS employeeName, date_format(bb.order_date, '%Y-%m-%d') AS orderDate, bb.order_num AS orderNum, date_format(bb.bill_date, '%Y-%m-%d') AS billDate, bb.bill_num AS billNum, bb.patient_id AS patientId, bp.`name`, bp.pinyin_name AS pinyinName, bp.mobile, bb.order_amount AS originalPrice, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS receivedAmount, bb.debt_amount AS debtAmount FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN ( SELECT btp.org_id, btp.treatment_id, btp.registered_dentist_id, be.employee_name FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treat_end_time IS NOT NULL ) btp ON bb.treatment_id = btp.treatment_id AND bb.org_id = btp.org_id
bb.debt_amount > 0
AND bb.org_id = #{form.orgId}
and DATE_FORMAT(bb.order_date, "%Y-%m-%d") >= DATE_FORMAT(#{form.startDate}, "%Y-%m-%d") and DATE_FORMAT(bb.order_date, "%Y-%m-%d") < DATE_FORMAT(#{form.endDate}, "%Y-%m-%d")
) t
AND t.regDentistId in
#{registeredDentistId}
and concat(IFNULL(t.`name`,''),IFNULL(t.pinyinName,''),IFNULL(t.mobile,'')) like concat(concat('%',#{form.combination}),'%')

SELECT bor.orderDate, bor.billId, bor.orderNum, bor.billNum, bor.patientId, bor.patientName, bor.mobile, bor.gender, bor.regDentistId, bor.regDentistName, IFNULL(bor.orderAmount,0) orderAmount, IFNULL(bor.privilegeAmount,0) privilegeAmount, IFNULL(bor.actualAmount,0) actualAmount, IFNULL(bor.receivedAmount,0) receivedAmount, bor.chargeStatus, bor.billerId, bor.biller FROM ( SELECT bb.org_id as orgId, DATE_FORMAT( bb.order_date, '%Y-%m-%d' ) AS orderDate, bb.bill_id AS billId, bb.order_num AS orderNum, bb.bill_num AS billNum, bb.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile AS mobile, bp.gender AS gender, btp.registered_dentist_id AS regDentistId, btp.employee_name AS regDentistName, bb.order_amount AS orderAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS receivedAmount, IF( bb.bill_num IS NULL OR bb.bill_num='', 0, 1 ) AS chargeStatus, bb.biller_id AS billerId, be.employee_name AS biller FROM base_bill bb LEFT JOIN ( SELECT btp.treatment_id, btp.registered_dentist_id, be.employee_name FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) btp ON bb.treatment_id = btp.treatment_id LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN base_employee be ON bb.biller_id = be.user_id ) bor
and bor.orgId = #{query.orgId}
and bor.orderNum like concat('%', #{query.orderNum} ,'%')
and bor.billNum like concat('%', #{query.billNum} ,'%')
and concat(IFNULL(bor.patientName, ''), IFNULL(bor.pinyinName, ''), IFNULL(bor.mobile, '')) like concat('%', #{query.keyWord}, '%')
and bor.orderDate >= #{query.orderStartDate}
and bor.orderDate <= #{query.orderEndDate}
and bor.regDentistId in
#{item}
ORDER BY bor.billId DESC

select billId, billDate, billNum, patientId, patientname, mobile, regDentistId, regDentistName, totalOriginalAmount, totalActualAmount, billReceivableAmount from ( select bb.bill_id as billId, date_format(bb.bill_date, '%Y-%m-%d') as billDate, bb.bill_num as billNum, bb.patient_id as patientId, bp.name as patientName, bp.pinyin_name as pinyinName, bp.mobile as mobile, btp.registered_dentist_id as regDentistId, be.employee_name as regDentistName, bb.order_amount as totalOriginalAmount, bb.actual_amount as totalActualAmount, bb.debt_amount as billReceivableAmount from base_bill bb left join base_patient bp on bb.patient_id = bp.patient_id left join base_treatment_process btp on bb.treatment_id = btp.treatment_id left join base_employee be on btp.registered_dentist_id = be.user_id
and bb.org_id = #{query.orgId}
AND date_format(bb.bill_date, '%Y-%m-%d') <= #{query.queryDate}
and btp.registered_dentist_id in
#{item}
) brr
brr.billReceivableAmount > 0
and concat(IFNULL(brr.patientName, ''), IFNULL(brr.pinyinName, ''), IFNULL(brr.mobile, '')) like concat('%', #{query.keyword}, '%')
order by brr.billDate desc, brr.billReceivableAmount desc

SELECT IFNULL(SUM( bb.totalOriginalAmount ), 0 ) AS totalOriginalAmount, IFNULL(SUM( bb.totalActualReceiveAmount ), 0) AS totalActualReceiveAmount, IFNULL(SUM( bb.totalDiscountAmount ), 0 ) AS totalDiscountAmount, IFNULL(SUM( bb.totalDebtAmount ), 0 ) AS totalDebtAmount, IFNULL(SUM(bb.totalFreePaymentAmount), 0) AS totalFreePaymentAmount FROM ( SELECT any_value(bb.org_id) as org_id, SUM( any_value(bb.order_amount) ) AS totalOriginalAmount, SUM( any_value(bb.privilege_amount) ) AS totalDiscountAmount, SUM( any_value(bb.actual_amount) ) AS totalActualReceiveAmount, SUM( any_value(bb.debt_amount) ) AS totalDebtAmount, SUM( any_value(bbpd.amount) ) AS totalFreePaymentAmount FROM base_bill bb LEFT JOIN ( SELECT bill_id, IFNULL(SUM(principal_amount), 0) amount FROM base_bill_pay_detail
type = 2
AND account_item_id IN
#{id}
GROUP BY bill_id ) bbpd ON bbpd.bill_id=bb.bill_id
AND bb.bill_date IS NOT NULL
and DATE_FORMAT( bb.bill_date, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT( bb.bill_date, '%Y') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y') <= #{query.endDate}
GROUP BY bb.org_id ) bb
and bb.org_id in
#{item}

SELECT bbd.orgId, bbd.orgName, bbd.billId, bbd.billDate, bbd.billNum, bbd.patientId, bbd.patientName, bbd.mobile, bbd.originalAmount, bbd.privilegeAmount, bbd.actualAmount, bbd.receivedAmount, bbd.remainingArrears FROM ( SELECT bbd.orgId, bbd.orgName, bbd.billId, bbd.billDate, bbd.billNum, bbd.patientId, bbd.patientName, bbd.pinyinName, bbd.mobile, bbd.originalAmount, bbd.privilegeAmount, bbd.actualAmount, bbd.receivedAmount, bbd.remainingArrears FROM ( SELECT any_value(bb.org_id) AS orgId, any_value(btp.registered_dentist_id) as registered_dentist_id, any_value(bo.abbreviation) AS orgName, any_value(bb.bill_id) AS billId, DATE_FORMAT(any_value(bb.bill_date), '%Y-%m-%d' ) AS billDate, any_value(bb.bill_num) AS billNum, any_value(bb.patient_id) AS patientId, any_value(bp.`name`) AS patientName, any_value(bp.pinyin_name) AS pinyinName, any_value(bp.mobile) as mobile, any_value(bb.originalAmount) as originalAmount, any_value(bb.privilegeAmount) as privilegeAmount, any_value(bb.actualAmount) as actualAmount, any_value(bb.receivedAmount) as receivedAmount, any_value(bb.remainingArrears) as remainingArrears FROM ( SELECT bb.org_id, bb.patient_id, bb.treatment_id, bb.bill_id, bb.bill_num, bb.bill_date, bb.order_amount AS originalAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS receivedAmount, bb.debt_amount AS remainingArrears FROM base_bill bb WHERE bb.debt_amount > 0 ) bb LEFT JOIN base_organization bo ON bb.org_id = bo.org_id LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN base_treatment_process btp ON bb.treatment_id = btp.treatment_id ) bbd
and bbd.registered_dentist_id = #{query.dentistId}
GROUP BY bbd.billId ) bbd
and bbd.billDate >= #{query.billStartDate}
and bbd.billDate <= #{query.billEndDate}
and concat(IFNULL(bbd.patientName, ''), IFNULL(bbd.pinyinName, ''), IFNULL(bbd.mobile, '')) like concat('%', #{query.keyword}, '%')

SELECT IFNULL(SUM( bb.actual_amount ), 0) AS totalActualAmountThisMonth, IFNULL(SUM( bb.privilege_amount ), 0) AS totalPrivilegeAmountThisMonth FROM base_bill bb
AND bb.bill_date IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.order_date, '%Y-%m' ) = #{query.queryDate}

select #{query.queryDate} as currentMonth, #{query.orgId} as orgId, IFNULL(SUM( bb.actual_amount ), 0) as currentMonthTotalActualAmount, IFNULL(SUM( bb.privilege_amount ), 0) as currentMonthTotalDiscountAmount, IFNULL(SUM( bb.received_amount ), 0) as currentMonthTotalReceivedAmount, IFNULL(SUM( bb.debt_amount ), 0) as currentMonthTotalDebtAmount from base_bill bb
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) = #{query.queryDate}

SELECT bb.bill_id as billId, DATE_FORMAT(bb.privilege_date, '%Y-%m-%d') AS collectDebtDate, bb.bill_num as billNum, DATE_FORMAT(bb.privilege_date, '%Y-%m') as billDate, bb.patient_id AS patientId, bp.`name` AS patientName, bp.mobile AS patientMobile, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName, bbp.payee_user_id as payeeId, be2.employee_name as payeeName FROM base_bill bb left join base_patient bp on bb.patient_id = bp.patient_id left join base_treatment_process btp on bb.treatment_id = btp.treatment_id left join base_employee be on btp.registered_dentist_id = be.user_id left join base_bill_pay bbp on bb.bill_id = bbp.bill_id and date_format(bb.privilege_date, '%Y-%m-%d %H:%i') = date_format(bbp.payee_date, '%Y-%m-%d %H:%i') left join base_employee be2 on bbp.payee_user_id = be2.user_id
and first_privilege = 0
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.privilege_date, '%Y-%m' ) = #{query.currentMonth}
order by bb.privilege_date

select
    bb.org_id AS orgId,
    patient_id AS patientId,
    sum(bb.actual_amount) as cumulativeConsumption,
    sum(bb.received_amount) as receivedAmount,
    sum(bb.debt_amount) as totalArrears
from base_bill bb

    AND bb.patient_id in

        #{id}



            AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) >= #{query.startDate}


