            AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) >= #{query.startDate}


            AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) <= #{query.endDate}




            AND DATE_FORMAT( bb.bill_date, '%Y' ) >= #{query.startDate}


            AND DATE_FORMAT( bb.bill_date, '%Y' ) <= #{query.endDate}



group by bb.patient_id, bb.org_id

SELECT bri.item_num AS itemNum, bri.item_name AS itemName, bri.category_name AS categoryName, bbf.benefitAmount, bbf.quantity, bc.coupon_name AS couponName, case when bc.coupon_type=0 then '代金券' when bc.coupon_type=1 then '折扣券' when bc.coupon_type=2 then '兑换券' when bc.coupon_type=3 then '套餐券' end AS couponType, bb.bill_num AS billNum, bb.bill_date AS billDate, bbf.quantity * bbd.price AS originPrice, bp. NAME AS patientName, bp.mobile AS patientMobile, bbd.price AS price, be.employee_name AS executor, bcd.card_number AS cardNumber, bcd.sale_channel_name AS saleChannelName FROM(SELECT bbf.org_id as orgId, bbf.coupon_id AS couponId, bbf.order_id AS orderId, bbf.card_id AS cardId, bbf.item_id AS itemId, bbf.item_type AS itemType, sum(ifnull(bbf.benefit_amount,0)) benefitAmount, count(1) AS quantity, bbf.order_detail_id AS orderDetailId FROM base_benefit bbf WHERE bbf.choice_benefit_type = 0 and bbf.coupon_type in (0,1,2,3) GROUP BY bbf.org_id,bbf.order_id,bbf.coupon_id,bbf.order_detail_id,bbf.card_id,bbf.item_id,bbf.item_type ) bbf LEFT JOIN base_bill bb ON bb.bill_id = bbf.orderId LEFT JOIN base_bill_detail bbd ON bbd.bill_detail_id = bbf.orderDetailId LEFT JOIN base_coupon bc ON bc.coupon_id = bbf.couponId LEFT JOIN base_patient bp ON bp.patient_id = bb.patient_id LEFT JOIN base_employee be ON bbd.executor_id = be.user_id LEFT JOIN base_card bcd ON bbf.cardId = bcd.card_id LEFT JOIN base_tariff_info bri ON (bri.item_id = bbf.itemId AND bri.item_type = bbf.itemType)
bb.bill_date is not null
and bbf.orgId = #{query.orgId}
and concat(IFNULL(bp.name, ''), IFNULL(bp.pinyin_name, ''), IFNULL(bp.mobile, '')) like concat('%', #{query.keyWord}, '%')
and bri.category_id in
#{item}
and bc.coupon_name = #{query.couponName}
and bcd.card_number = #{query.cardNumber}
and DATE_FORMAT(bb.bill_date,'%Y-%m-%d') between DATE_FORMAT(#{query.orderStartDate},'%Y-%m-%d') and DATE_FORMAT(#{query.orderEndDate},'%Y-%m-%d')
order by bb.bill_id desc

